from __future__ import annotations

import csv
import json
import sys
from pathlib import Path
from typing import Any, Callable, Iterable, Mapping


class HarnessError(Exception):
    \"\"\"Raised when the harness cannot process requested inputs.\"\"\"


MAX_RETRIES = 2
STAGES = (\"extract\", \"clean\", \"report\")


def load_config(config_path: str | Path = \"config/m2.json\") -> dict[str, Any]:
    \"\"\"Load a small JSON or YAML configuration file.\"\"\"
    path = Path(config_path)
    if not path.exists():
        raise HarnessError(f\"Config file not found: {config_path}\")

    suffix = path.suffix.lower()
    text = path.read_text(encoding=\"utf-8\")
    if suffix == \".json\":
        try:
            data = json.loads(text)
        except json.JSONDecodeError as exc:
            raise HarnessError(f\"Invalid JSON config {config_path}: {exc.msg}\") from exc
    elif suffix in {\".yaml\", \".yml\"}:
        data = _parse_simple_yaml(text)
    else:
        raise HarnessError(f\"Unsupported config file type: {config_path}\")

    if not isinstance(data, dict):
        raise HarnessError(f\"Config must be an object: {config_path}\")
    return data


def _parse_simple_yaml(text: str) -> dict[str, Any]:
    data: dict[str, Any] = {}
    for line_number, raw_line in enumerate(text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith(\"#\"):
            continue
        if \":\" not in line:
            raise HarnessError(f\"Invalid YAML config at line {line_number}\")
        key, value = line.split(\":\", 1)
        key = key.strip()
        value = value.strip()
        if not key:
            raise HarnessError(f\"Invalid YAML config at line {line_number}\")
        if (value.startswith('\"') and value.endswith('\"')) or (value.startswith(\"'\") and value.endswith(\"'\")):
            value = value[1:-1]
        data[key] = value
    return data


def _has_non_empty_id(record: Mapping[str, Any]) -> bool:
    for key, value in record.items():
        if str(key).lower() == \"id\":
            return value is not None and str(value).strip() "'!= ""
    return False


def _csv_records(path: Path) -> Iterable[Mapping[str, Any]]:
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        reader = csv.DictReader(row for row in handle if row.strip())
        for row in reader:
            yield row


def _jsonl_records(path: Path) -> Iterable[Mapping[str, Any]]:
    with path.open("r", encoding="utf-8") as handle:
        for line_number, line in enumerate(handle, start=1):
            if not line.strip():
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError as exc:
                raise HarnessError(f"Invalid JSON in {path} at line {line_number}: {exc.msg}") from exc
            if not isinstance(record, dict):
                raise HarnessError(f"JSONL record in {path} at line {line_number} is not an object")
            yield record


def _records_for(path: Path) -> Iterable[Mapping[str, Any]]:
    suffix = path.suffix.lower()
    if suffix == ".csv":
        return _csv_records(path)
    if suffix == ".jsonl":
        return _jsonl_records(path)
    raise HarnessError(f"Unsupported input file type: {path}")


def _log(stage: str, status: str, attempt: int, log_stream: Any, **extra: Any) -> None:
    if log_stream is None:
        return
    entry = {"stage": stage, "status": status, "attempt": attempt}
    entry.update(extra)
    print(json.dumps(entry, ensure_ascii=False), file=log_stream)


def _run_stage(stage: str, action: Callable[[], Any], log_stream: Any) -> tuple[Any, int]:
    retries = 0
    for attempt in range(1, MAX_RETRIES + 2):
        _log(stage, "started", attempt, log_stream)
        try:
            result = action()
        except Exception as exc:
            if attempt <= MAX_RETRIES:
                retries += 1
                _log(stage, "retry", attempt, log_stream, error=str(exc))
                continue
            _log(stage, "failed", attempt, log_stream, error=str(exc))
            raise
        _log(stage, "succeeded", attempt, log_stream)
        return result, retries
    raise HarnessError(f"Stage failed: {stage}")


def _extract(source_files: list[str]) -> list[Mapping[str, Any]]:
    records: list[Mapping[str, Any]] = []
    for source in source_files:
        path = Path(source)
        if not path.exists():
            raise HarnessError(f"Input file not found: {source}")
        records.extend(_records_for(path))
    return records


def _clean(records: Iterable[Mapping[str, Any]]) -> tuple[int, int]:
    processed_count = 0
    rejected_count = 0
    for record in records:
        if _has_non_empty_id(record):
            processed_count += 1
        else:
            rejected_count += 1
    return processed_count, rejected_count


def _build_report(
    processed_count: int,
    rejected_count: int,
    retry_count: int,
    source_files: list[str],
    config: Mapping[str, Any],
) -> dict[str, Any]:
    report = {
        "processed_count": processed_count,
        "rejected_count": rejected_count,
        "retry_count": retry_count,
        "source_files": source_files,
    }
    if "report_label" in config:
        report["report_label"] = config["report_label"]
    return report


def _write_report(report: Mapping[str, Any], output: str | Path | None) -> None:
    if output is not None:
        output_path = Path(output)
        output_path.parent.mkdir(parents=True, exist_ok=True)
        output_path.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "'"\\n\", encoding=\"utf-8\")


def run_dag(
    input_files: Iterable[str | Path],
    output: str | Path | None = None,
    config: str | Path | Mapping[str, Any] | None = None,
    log_stream: Any = sys.stderr,
) -> dict[str, Any]:
    \"\"\"Run the extract -> clean -> report DAG with up to two retries per stage.\"\"\"
    source_files = [str(path) for path in input_files]
    loaded_config = dict(config) if isinstance(config, Mapping) else load_config(config or \"config/m2.json\")
    retry_count = 0

    records, retries = _run_stage(\"extract\", lambda: _extract(source_files), log_stream)
    retry_count += retries
    counts, retries = _run_stage(\"clean\", lambda: _clean(records), log_stream)
    retry_count += retries
    processed_count, rejected_count = counts

    report: dict[str, Any] = {}

    def report_action() -> dict[str, Any]:
        built_report = _build_report(processed_count, rejected_count, retry_count, source_files, loaded_config)
        _write_report(built_report, output)
        return built_report

    report, retries = _run_stage(\"report\", report_action, log_stream)
    if retries:
        retry_count += retries
        report = _build_report(processed_count, rejected_count, retry_count, source_files, loaded_config)
        _write_report(report, output)
    return report
